package cn.mop.contactworker;
import java.time.Duration;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Isolated lifecycle tests, not evidence of database processing or process restart. */
class ContactImportWorkerRuntimeTest {
    ContactImportWorkerRuntime runtime(java.util.function.BooleanSupplier ready,ContactImportWorkerRuntime.Processor processor){return new ContactImportWorkerRuntime(ready,processor,Duration.ofSeconds(30),500);}
    @Test void unavailableSchemaNeverStartsOrClaims(){var calls=new AtomicInteger();var r=runtime(()->false,(owner,lease)->{calls.incrementAndGet();return true;});assertThrows(IllegalStateException.class,r::start);assertFalse(r.isRunning());assertEquals(false,r.dependencyReady());assertEquals(0,calls.get());}
    @Test void startupExceptionIsRedactedAndNoThreadIsStarted(){var r=runtime(()->{throw new IllegalStateException("SYNTHETIC_SECRET");},(owner,lease)->true);var failure=assertThrows(IllegalStateException.class,r::start);assertFalse(failure.getMessage().contains("SYNTHETIC_SECRET"));assertNull(failure.getCause());assertFalse(r.isRunning());}
    @Test void startsSingleSerialThreadAndUsesExplicitLease()throws Exception{var entered=new CountDownLatch(1);var active=new AtomicInteger();var maximum=new AtomicInteger();var r=runtime(()->true,(owner,lease)->{assertTrue(owner.startsWith("contact-import-worker-"));assertTrue(owner.length()<=64);assertEquals(Duration.ofSeconds(30),lease);int n=active.incrementAndGet();maximum.accumulateAndGet(n,Math::max);entered.countDown();try{Thread.sleep(10);}catch(InterruptedException stopped){Thread.currentThread().interrupt();}finally{active.decrementAndGet();}return false;});try{r.start();r.start();assertTrue(entered.await(2,TimeUnit.SECONDS));assertEquals(1,maximum.get());assertTrue(r.isRunning());}finally{r.stop();}assertFalse(r.isRunning());assertNull(r.dependencyReady());}
    @Test void lossOfReadinessPreventsClaimAndDoesNotLookReady()throws Exception{var checks=new AtomicInteger();var calls=new AtomicInteger();var unavailable=new CountDownLatch(1);var r=runtime(()->{if(checks.incrementAndGet()==1)return true;unavailable.countDown();return false;},(owner,lease)->{calls.incrementAndGet();return true;});try{r.start();assertTrue(unavailable.await(2,TimeUnit.SECONDS));long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(1);while(!Boolean.FALSE.equals(r.dependencyReady())&&System.nanoTime()<deadline)Thread.sleep(1);assertEquals(false,r.dependencyReady());assertEquals(0,calls.get());}finally{r.stop();}}
    @Test void dependencyExceptionBacksOffAndClearsReady()throws Exception{var called=new CountDownLatch(1);var r=runtime(()->true,(owner,lease)->{called.countDown();throw new IllegalStateException("SYNTHETIC_FAILURE");});try{r.start();assertTrue(called.await(2,TimeUnit.SECONDS));long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(1);while(!Boolean.FALSE.equals(r.dependencyReady())&&System.nanoTime()<deadline)Thread.sleep(1);assertEquals(false,r.dependencyReady());}finally{r.stop();}}
    @Test void stopCallbackRunsAndStoppedRuntimeHasUnknownReadiness(){var called=new AtomicInteger();var r=runtime(()->true,(owner,lease)->false);r.stop(called::incrementAndGet);assertEquals(1,called.get());assertFalse(r.isRunning());assertNull(r.dependencyReady());assertTrue(r.isAutoStartup());assertEquals(Integer.MAX_VALUE,r.getPhase());}
    @Test void cannotRestartWhilePreviousOperationStillIgnoresInterrupt()throws Exception{var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var r=new ContactImportWorkerRuntime(()->true,(owner,lease)->{entered.countDown();boolean done=false;while(!done){try{release.await();done=true;}catch(InterruptedException ignored){}}return true;},Duration.ofSeconds(30),10);try{r.start();assertTrue(entered.await(2,TimeUnit.SECONDS));r.stop();assertThrows(IllegalStateException.class,r::start);}finally{release.countDown();r.stop();}}
    @Test void invalidRuntimeTimingCannotStart(){assertThrows(IllegalArgumentException.class,()->new ContactImportWorkerRuntime(()->true,(owner,lease)->false,Duration.ofMillis(999),500));assertThrows(IllegalArgumentException.class,()->new ContactImportWorkerRuntime(()->true,(owner,lease)->false,Duration.ofHours(2),500));assertThrows(IllegalArgumentException.class,()->new ContactImportWorkerRuntime(()->true,(owner,lease)->false,Duration.ofSeconds(30),0));}
}
